    '𐤎𐤏': '𐤍𐤎𐤏',
    // Gad (Gamal-Dalet) -> Nagad (Nun-Gamal-Dalet): Nun assimilates into Gamal. TRUE ROOT: Nagad (𐤍𐤂𐤃) "to declare/tell/announce"
    '𐤂𐤃': '𐤍𐤂𐤃',
