    //   The homographs.json should carry: "𐤍𐤐𐤔_subs" and "𐤍𐤐𐤔_verb"
    '𐤐𐤔': '𐤍𐤐𐤔',
    // Pal (Peh-Lamad) -> NaPal (Nun-Peh-Lamad): already present above as '𐤐𐤋': '𐤍𐤐𐤋'
    // Pakad (Peh-Kap-Dalet) -> surface Pak (Peh-Kap): Nun assimilates.
