    '𐤒𐤍': '𐤒𐤍𐤄',
    // Ban (Bayath-Nun) -> Banah (Bayath-Nun-Hay): final Hay drops. TRUE ROOT: Banah (𐤁𐤍𐤄) "to build"
    '𐤁𐤍': '𐤁𐤍𐤄',
    // Gal (Gamal-Lamad) -> Galah (Gamal-Lamad-Hay): final Hay drops. TRUE ROOT: Galah (𐤂𐤋𐤄) "to uncover/reveal/go into exile"
    '𐤂𐤋': '𐤂𐤋𐤄',
